//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::nat::mul_small`; the
//! native twin is `benches/native/Bench/NatMulSmall.lean`.
//! Nat words on both sides (2n+1); every result stays below 2^63; the word helper on unboxed
//! words, the glue's own fast path

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::nat;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let r = nat::mul_small(
                nat_unbox(nat_box(x >> 34)),
                nat_unbox(nat_box((x >> 4) & 0x3FFF_FFFF)),
            );
            nat_unbox(if r >> 63 == 0 {
                nat_box(r as u64)
            } else {
                big()
            })
        });
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
